<?php require 'config.php'; if(user()){header('Location: dashboard.php');exit;} $err=''; if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$u=trim($_POST['username']??'');$e=trim($_POST['email']??'');$p=$_POST['password']??''; if(!preg_match('/^[A-Za-z0-9_]{3,24}$/',$u))$err='Ник: 3–24 символа, только латиница, цифры и _. '; elseif(!filter_var($e,FILTER_VALIDATE_EMAIL))$err='Введите корректную почту.'; elseif(strlen($p)<8)$err='Пароль должен быть минимум 8 символов.'; else{try{$s=db()->prepare('INSERT INTO users(username,email,password_hash,created_at) VALUES(?,?,?,?)');$s->execute([$u,$e,password_hash($p,PASSWORD_DEFAULT),time()]);$_SESSION['uid']=db()->lastInsertId();header('Location: dashboard.php');exit;}catch(Throwable $x){$err='Ник или email уже занят.';}}} ?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Регистрация — Fly Client</title><link rel="stylesheet" href="assets/style.css"></head><body><?php require 'header.php'; ?><div class="wrap"><form class="form card" method="post"><h1>Создать аккаунт</h1><p class="muted">Доступ к личному кабинету и скачиванию.</p><?php if($err):?><div class="notice danger"><?=e($err)?></div><?php endif;?><input type="hidden" name="csrf" value="<?=csrf()?>"><label class="label">Никнейм</label><input class="input" name="username" required><label class="label">Email</label><input class="input" type="email" name="email" required><label class="label">Пароль</label><input class="input" type="password" name="password" required><button class="btn primary" style="width:100%">Создать аккаунт</button></form></div></body></html>
